void InOrderNonRecursive(BiTree T) {
    Stack S;
    InitStack(S);
    BiTree p = T;

    while (p || !IsEmpty(S)) {
        if (p) {
            Push(S, p);      // 根结点入栈
            p = p->lchild;   // 走向左子树
        } else {
            Pop(S, p);       // 弹出栈顶
            visit(p);        // 访问根结点
            p = p->rchild;   // 走向右子树
        }
    }
}
