#define MAXN 1000

int parent[MAXN];  // 双亲指针，根结点的双亲为自身
int rank[MAXN];    // 秩，可理解为树高的上界

// 初始化：每个元素自成一个集合
void Init(int n) {
    for (int i = 0; i < n; i++) {
        parent[i] = i;
        rank[i] = 0;
    }
}

// 查找：带路径压缩
int Find(int x) {
    int root = x;

    // 先找到根
    while (parent[root] != root) {
        root = parent[root];
    }

    // 再将路径上的结点直接挂到根
    while (parent[x] != root) {
        int p = parent[x];
        parent[x] = root;
        x = p;
    }

    return root;
}

// 合并：按秩合并
void Union(int x, int y) {
    int rx = Find(x);
    int ry = Find(y);

    if (rx == ry) {
        return;  // 已属于同一集合，无需合并
    }

    if (rank[rx] < rank[ry]) {
        parent[rx] = ry;
    } else if (rank[rx] > rank[ry]) {
        parent[ry] = rx;
    } else {
        parent[ry] = rx;
        rank[rx]++;
    }
}
```

