 *   a、b 的低 n 位为补码编码
 *   *overflow = true 表示有符号溢出
 *
 * 返回值：
 *   0 表示参数合法
 *  -1 表示参数非法
 */
int add_complement(int n, uint32_t a, uint32_t b,
                   uint32_t *sum, bool *overflow)
{
    if (n < 2 || n > 32 || !sum || !overflow)
        return -1;

    /* 只保留低 n 位补码编码 */
    uint64_t mask = (n == 32) ? UINT64_C(0xFFFFFFFF)
                              : ((UINT64_C(1) << n) - 1);

    uint64_t x = a & mask;
    uint64_t y = b & mask;

    /*
     * 补码加法：符号位参与运算。
     * full 保存未截断结果，用于观察进位。
     */
    uint64_t full = x + y;

    /* n 位补码结果 */
    *sum = (uint32_t)(full & mask);

    /*
     * 符号位进位：第 n-1 位向第 n 位的进位。
     * 即最高符号位是否产生进位。
     */
    unsigned carry_sign = (unsigned)((full >> n) & 1);

    /*
     * 次高位进位：第 n-2 位向第 n-1 位的进位。
     * 它只由低 n-1 位相加产生。
     */
    uint64_t low_mask = (UINT64_C(1) << (n - 1)) - 1;
    uint64_t low_sum = (x & low_mask) + (y & low_mask);
    unsigned carry_into_sign = (unsigned)((low_sum >> (n - 1)) & 1);

    /*
     * 资料给出的判定思想：
     * 符号位进位与次高位进位不一致，则有符号溢出。
     */
    *overflow = (carry_sign ^ carry_into_sign) != 0;

    return 0;
}
```

如果两个补码整数是 32 位 `int32_t`，可以这样封装：

```c
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

int add_int32_complement(int32_t a, int32_t b,
                         int32_t *sum, bool *overflow)
{
    uint32_t ua, ub, us;

    /* 按位取出补码编码 */
    memcpy(&ua, &a, sizeof ua);
    memcpy(&ub, &b, sizeof ub);

    int ret = add_complement(32, ua, ub, &us, overflow);
    if (ret != 0)
        return ret;

    /* 把低 32 位补码结果写回 int32_t */
    memcpy(sum, &us, sizeof *sum);
    return 0;
}
```

