```c
#include <stdio.h>
#include <math.h>

typedef struct {
    long double bit_per_sec;       // 带宽，单位 bit/s
    long double byte_per_sec;      // 带宽，单位 B/s，精确值
    long double byte_per_sec_ceil; // 若必须取完整字节，向上取整后的 B/s
} BusBandwidth;

/*
 * 根据总线宽度和工作频率计算总线带宽
 *
 * width_bits: 总线宽度，单位 bit
 * work_freq_hz: 工作频率，单位 Hz，即每秒传输次数
 * transfers_per_cycle: 每个周期传输次数，通常为 1；若题目说明双倍传输，可按题给定
 */
int calc_bus_bandwidth(unsigned int width_bits,
                       long double work_freq_hz,
                       long double transfers_per_cycle,
                       BusBandwidth *result)
{
    if (result == NULL) {
        return -1;
    }

    if (work_freq_hz < 0 || transfers_per_cycle < 0) {
        return -1;
    }

    /*
     * 资料公式：
     * 带宽 = 工作频率 × 宽度 × 每周期传送次数
     */
    result->bit_per_sec =
        (long double)width_bits * work_freq_hz * transfers_per_cycle;

    /*
     * 位宽不是 8 的整数倍时：
     * 必须使用浮点除法，不能写成 width_bits / 8。
     */
    result->byte_per_sec = result->bit_per_sec / 8.0L;

    /*
     * 如果题目要求以完整字节表示，可以向上取整。
     * 资料未强制规定取整方式，这里仅作为可选处理。
     */
    result->byte_per_sec_ceil = ceill(result->byte_per_sec);

    return 0;
}

/*
 * 如果题目给的是时钟频率，而不是工作频率，
 * 且一个总线周期包含 N 个时钟周期，则：
 * 工作频率 = 时钟频率 / N
 */
int calc_bus_bandwidth_from_clock(unsigned int width_bits,
                                  long double clock_freq_hz,
                                  unsigned int clocks_per_bus_cycle,
                                  long double transfers_per_cycle,
                                  BusBandwidth *result)
{
    if (clocks_per_bus_cycle == 0) {
        return -1;
    }

    long double work_freq_hz =
        clock_freq_hz / (long double)clocks_per_bus_cycle;

    return calc_bus_bandwidth(width_bits,
                              work_freq_hz,
                              transfers_per_cycle,
                              result);
}

int main(void)
{
