    /*
     * 示例：
     * 总线宽度 36 bit
     * 工作频率 100 MHz
     * 每周期传输 1 次
     */
    unsigned int width_bits = 36;
    long double work_freq_hz = 100000000.0L;
    long double transfers_per_cycle = 1.0L;

    if (calc_bus_bandwidth(width_bits,
                           work_freq_hz,
                           transfers_per_cycle,
                           &bw) == 0) {
        printf("总线宽度: %u bit\n", width_bits);
        printf("工作频率: %.0Lf Hz\n", work_freq_hz);
        printf("总线带宽: %.2Lf bit/s\n", bw.bit_per_sec);
        printf("总线带宽: %.6Lf B/s\n", bw.byte_per_sec);
        printf("若按完整字节向上取整: %.0Lf B/s\n", bw.byte_per_sec_ceil);
    }

    /*
     * 示例二：
     * 给的是时钟频率 200 MHz，
     * 一个总线周期包含 4 个时钟周期，
     * 总线宽度 64 bit。
