    BusBandwidth bw2;

    unsigned int width_bits2 = 64;
    long double clock_freq_hz2 = 200000000.0L;
    unsigned int clocks_per_bus_cycle2 = 4;
    long double transfers_per_cycle2 = 1.0L;

