                                      clock_freq_hz2,
                                      clocks_per_bus_cycle2,
                                      transfers_per_cycle2,
                                      &bw2) == 0) {
        printf("\n");
        printf("总线宽度: %u bit\n", width_bits2);
        printf("时钟频率: %.0Lf Hz\n", clock_freq_hz2);
        printf("总线周期时钟数: %u\n", clocks_per_bus_cycle2);
        printf("工作频率: %.0Lf Hz\n",
