    while (true) {
        P(full);        // 申请一个满缓冲区
        P(mutex);       // 申请互斥访问缓冲区

        从缓冲区取出一个产品;

        V(mutex);       // 释放缓冲区互斥访问
        V(empty);       // 增加一个空缓冲区

