```c
#include <stdint.h>

/*
 * 模 2 除法
 * dividend : 被除数
 * bits     : dividend 的有效位数
 * poly     : 生成多项式对应的二进制串，共 r+1 位，最高位为 1
 * r        : 生成多项式次数，也是 CRC 校验位数
 * 返回值   : r 位余数
 */
static uint32_t mod2_div(uint32_t dividend, int bits, uint32_t poly, int r)
{
    uint32_t mask = (1U << r) - 1U;

    for (int i = bits - 1; i >= r; --i) {
        if ((dividend >> i) & 1U) {
            dividend ^= (poly << (i - r));  /* 模 2 除：异或 */
        }
    }

    return dividend & mask;  /* 保留 r 位余数 */
}

/*
 * 发送端：计算 CRC 校验位 / FCS
 * data : 原始数据，低 m 位有效
 * m    : 数据位数
 * poly : 生成多项式对应的二进制串，共 r+1 位
 * r    : 校验位数
 */
uint32_t crc_fcs(uint32_t data, int m, uint32_t poly, int r)
{
    uint32_t dividend = data << r;  /* M·2^r，末尾补 r 个 0 */
    return mod2_div(dividend, m + r, poly, r);
}

/*
 * 发送端：生成完整码字
 * 返回：T = M·2^r + R
 */
uint32_t crc_make_frame(uint32_t data, int m, uint32_t poly, int r)
{
    uint32_t fcs = crc_fcs(data, m, poly, r);
    return (data << r) | fcs;
}

/*
 * 接收端：CRC 校验
 * frame : 接收到的完整码字，低 m+r 位有效
 * 返回：1 表示余数为 0，认为无差错；0 表示检测出错
 */
int crc_check(uint32_t frame, int m, uint32_t poly, int r)
{
    uint32_t rem = mod2_div(frame, m + r, poly, r);
    return rem == 0;
}
```

说明：

- `r` 是生成多项式次数，也是校验位数。
- `poly` 表示 `r + 1` 位生成多项式二进制串。
- 发送端先左移 `r` 位，再通过模 2 除法得到 `r` 位余数，作为 FCS。
- 接收端对完整码字做同样的模 2 除法，余数为 0 则认为无差错。
- CRC 只能检错，不能纠错。
